var c=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.RuntimeAnimatorController>("Assets/Animations/Player/PlayerDirectional.controller"); int count=0;foreach(var clip in c.animationClips.Distinct()) foreach(var binding in UnityEditor.AnimationUtility.GetObjectReferenceCurveBindings(clip)) foreach(var key in UnityEditor.AnimationUtility.GetObjectReferenceCurve(clip,binding)) {if(!(key.value is UnityEngine.Sprite)) throw new System.Exception("Missing sprite in "+clip.name); count++;} return c.animationClips.Distinct().Count()+" clips, "+count+" valid sprite keys; no missing sprites.";
